<?php require __DIR__ . '/includes/config.php';require_login();$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['user']['id']]);$orders=$s->fetchAll();$pageTitle='Orders';require __DIR__ . '/includes/header.php'; ?><section class="container py-5"><div class="eyebrow">Account</div><h1 class="display-5 mb-4">Your orders</h1><div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Order</th><th>Date</th><th>Status</th><th class="text-end">Total</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td>#<?= $order['id'] ?></td><td><?= date('M j, Y',strtotime($order['created_at'])) ?></td><td><span class="badge text-bg-light"><?= e($order['status']) ?></span></td><td class="text-end">$<?= number_format($order['total'],2) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$orders): ?><p class="mb-0 text-secondary">You have not placed an order yet.</p><?php endif; ?></div></section><?php require __DIR__ . '/includes/footer.php'; ?>